40:    if !is_network {
41:        match windows::windows_copyfile(src, dst) {
42:            Ok(bytes) => {
43:                let clone_succeeded = windows::take_last_block_clone_success();
44:                if !clone_succeeded {
45:                    metadata::preserve_metadata(src, dst)?;
46:                } else {
47:                    log::debug!(
48:                        "block clone preserved metadata automatically for {}",
49:                        dst.display()
50:                    );
51:                }
52:                return Ok(FileCopyOutcome {
53:                    bytes_copied: bytes,
54:                    clone_succeeded,
55:                });
56:            }
57:            Err(err) => {
58:                log::warn!(
59:                    "windows_copyfile fallback to streaming copy for {}: {}",
60:                    src.display(),
61:                    err
62:                );
63:            }
64:        }
65:    }
66:
67:    let result: Result<FileCopyOutcome> = (|| {
68:        let metadata = fs::metadata(src)?;
69:        let file_size = metadata.len();
70:
71:        let buffer_size = buffer_sizer.calculate_buffer_size(file_size, is_network);
72:
73:        if let Some(parent) = dst.parent() {
74:            fs::create_dir_all(parent)?;
75:        }
76:
77:        let parent = dst
78:            .parent()
79:            .ok_or_else(|| eyre!("destination has no parent: {}", dst.display()))?;
80:        fs::create_dir_all(parent)?;
81:
82:        #[cfg(windows)]
83:        use std::os::windows::fs::OpenOptionsExt;
84:        #[cfg(windows)]
85:        let src_file = {
86:            std::fs::OpenOptions::new()
87:                .read(true)
88:                .custom_flags(FILE_FLAG_SEQUENTIAL_SCAN)
89:                .open(src)?
90:        };
