105:        // to NOT exist (returns EEXIST otherwise). Pre-fix the
106:        // unconditional `File::create(dst)` above created an empty
107:        // file before the clone attempt, so clonefile ALWAYS failed
108:        // with EEXIST and APFS clones never succeeded. Defer the
109:        // create to the fallback streaming path; the clone branch
110:        // doesn't need a pre-existing destination handle.
111:        #[cfg(target_os = "macos")]
112:        let dst_file: Option<File> = None;
113:        #[cfg(all(unix, not(target_os = "macos")))]
114:        let dst_file = create_regular(dst)?;
115:
116:        let (total_bytes, clone_succeeded) = {
117:            #[cfg(windows)]
118:            {
119:                let mut clone_success = false;
120:                if crate::fs_capability::supports_block_clone_same_volume(src, dst)? {
121:                    match windows::try_block_clone_with_handles(&src_file, &dst_file, file_size)? {
122:                        windows::BlockCloneOutcome::Cloned => {
123:                            clone_success = true;
124:                            log::info!("block clone {} ({} bytes)", dst.display(), file_size);
125:                        }
126:                        windows::BlockCloneOutcome::Unsupported { code } => {
127:                            crate::fs_capability::mark_block_clone_unsupported(src, dst);
128:                            log::debug!(
129:                                "block clone unsupported for {} (error code {code}); falling back",
130:                                dst.display()
131:                            );
132:                        }
133:                        windows::BlockCloneOutcome::PrivilegeUnavailable => {
134:                            log::trace!(
135:                                "block clone privilege unavailable for {}; falling back",
136:                                dst.display()
137:                            );
138:                        }
139:                        windows::BlockCloneOutcome::Failed(err) => {
140:                            log::debug!(
141:                                "block clone streaming fallback for {} ({err})",
142:                                dst.display()
143:                            );
144:                        }
145:                    }
146:                }
147:                if clone_success {
148:                    (file_size, true)
149:                } else {
150:                    let copied = clone::sparse_copy_windows(
151:                        src_file,
152:                        &mut dst_file,
153:                        buffer_size,
154:                        file_size,
155:                    )?;
156:                    (copied, false)
157:                }
158:            }
159:            #[cfg(target_os = "macos")]
160:            {
161:                let _ = dst_file; // silence unused on this branch (always None)
162:                                  // R58-F11: try clone primitives FIRST (they need
