169:                if cloned {
170:                    (file_size, true)
171:                } else {
172:                    let dst_for_stream = create_regular(dst)?;
173:                    let mut reader = BufReader::with_capacity(buffer_size, src_file);
174:                    let mut writer = BufWriter::with_capacity(buffer_size, dst_for_stream);
175:                    let n = io::copy(&mut reader, &mut writer)?;
176:                    writer.flush()?;
177:                    (n, false)
178:                }
179:            }
180:            #[cfg(all(unix, not(target_os = "macos")))]
181:            {
182:                let fast_linux =
183:                    clone::attempt_copy_file_range_linux(&src_file, &dst_file, file_size)
184:                        .unwrap_or(false)
185:                        || clone::attempt_sendfile_linux(&src_file, &dst_file, file_size)
186:                            .unwrap_or(false);
187:                if fast_linux {
188:                    (file_size, true)
189:                } else if let Some(n) =
190:                    clone::attempt_sparse_copy_unix(&src_file, &dst_file, file_size)?
191:                {
192:                    (n, false)
193:                } else {
194:                    let mut reader = BufReader::with_capacity(buffer_size, src_file);
195:                    let mut writer = BufWriter::with_capacity(buffer_size, dst_file);
196:                    let n = io::copy(&mut reader, &mut writer)?;
197:                    writer.flush()?;
198:                    (n, false)
199:                }
200:            }
201:        };
202:        if !clone_succeeded || !A_CLONE_CARRIES_METADATA {
203:            metadata::preserve_metadata(src, dst)?;
204:        }
205:
206:        Ok(FileCopyOutcome {
207:            bytes_copied: total_bytes,
208:            clone_succeeded,
209:        })
210:    })();
