3293:fn settle_failed_target_known(
3294:    dst: &Path,
3295:    handle: Option<std::fs::File>,
3296:    source_size: u64,
3297:    on_failure: OnFailure,
3298:    known: Option<(u64, u64)>,
3299:) -> Settled {
3300:    let mark = |handle: Option<&std::fs::File>| match handle {
3301:        Some(file) => mark_unfinished(file, source_size),
3302:        None => std::fs::OpenOptions::new()
3303:            .write(true)
3304:            .open(dst)
3305:            .and_then(|file| mark_unfinished(&file, source_size)),
3306:    };
3307:    let remove = || match std::fs::remove_file(dst) {
3308:        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
3309:        other => other,
3310:    };
