3324:            // removed: it is marked through the handle and reported left in
3325:            // place; or somebody else's file, left alone. Asked again
3326:            // before the second removal, for the name can change between.
3327:            let held = handle
3328:                .as_ref()
3329:                .and_then(|file| file.metadata().ok())
3330:                .as_ref()
3331:                .and_then(file_identity)
3332:                .or(known);
3333:            let followed_to_held = || {
3334:                held.is_some_and(|held| {
3335:                    std::fs::metadata(dst).ok().as_ref().and_then(file_identity) == Some(held)
3336:                })
3337:            };
3338:            let not_its_own = || held.is_some_and(|held| identity_at(dst) != Some(held));
