3340:                let note = match marked {
3341:                    Ok(()) => format!(
3342:                        "{INCOMPLETE_LEFT_IN_PLACE}: its name is a link to it, which is not \
3343:                         this run's to remove, so it was left one byte longer than the source"
3344:                    ),
3345:                    Err(mark_error) => format!(
3346:                        "{INCOMPLETE_LEFT_IN_PLACE}: its name is a link to it, and it could not \
3347:                         be marked unfinished ({mark_error})"
3348:                    ),
3349:                };
