3371:            if not_its_own() {
3372:                if !followed_to_held() {
3373:                    return REMOVED;
3374:                }
3375:                return left_through_a_link(marked);
3376:            }
3377:            let remove_error = match remove() {
3378:                Ok(()) => return REMOVED,
3379:                Err(error) => error,
3380:            };
