95:impl RunTotals {
96:    /// Add `other`'s account to this one: the parts of one run.
97:    pub fn merge(&mut self, other: RunTotals) {
98:        self.files_copied += other.files_copied;
99:        self.files_deleted += other.files_deleted;
100:        self.files_failed += other.files_failed;
101:        self.bytes_copied += other.bytes_copied;
102:        self.files_resumed += other.files_resumed;
103:        self.in_stream_carrier = match (self.in_stream_carrier, other.in_stream_carrier) {
104:            (Some(a), Some(b)) => Some(a || b),
105:            (a, b) => a.or(b),
106:        };
107:        self.failed_paths.extend(other.failed_paths);
108:        self.failed_paths_truncated |= other.failed_paths_truncated;
109:        self.failures.extend(other.failures);
110:        self.left_in_place.extend(other.left_in_place);
111:        self.left_in_place_truncated |= other.left_in_place_truncated;
112:        self.left_in_place_raw.extend(other.left_in_place_raw);
113:    }
114:}
