196:                match self.failed_paths_raw.get(at) {
197:                    Some(raw) if !raw.is_empty() => {
198:                        set.raw.insert(raw.clone());
199:                    }
200:                    _ => {
201:                        set.text.insert(PathBuf::from(path));
