211:        // when its named paths fit; the count exposes the gap, and the
212:        // set is then inexact — the difference must survive as unretried,
213:        // never be cleared by a later clean pass.
214:        let represented = (self.failed_paths.len() as u64).saturating_add(self.unretried);
