51:impl RemoteEndpoint {
52:    /// The one statement of blit's default daemon port (w7-6): the
53:    /// daemon's bind default, `blit scan`'s display elision, and the
54:    /// TUI's local-row fallback all reference this constant.
55:    pub const DEFAULT_PORT: u16 = 9031;
