57:    pub fn parse(raw: &str) -> Result<Self> {
58:        // cr-uv1-1: what follows the host is a PATH, and a space at the
59:        // end of a path is part of its last name. The whole text was
60:        // trimmed here, so `host:/m/report ` named `report` — another
61:        // file, and `rm` removed it. Only what comes before the host is
62:        // set aside; a bare host, which holds no path, is trimmed below.
63:        let trimmed = raw.trim_start();
64:        if trimmed.trim_end().is_empty() {
65:            bail!("remote location cannot be empty");
66:        }
67:
68:        match check_local_path(trimmed) {
69:            LocalPathCheck::IsLocal => return Err(NotRemote::LocalPath.into()),
70:            LocalPathCheck::RemoteWithBackslashes => {
71:                return Err(NotRemote::Backslashes(trimmed.to_string()).into());
72:            }
73:            LocalPathCheck::NotLocal => {}
74:        }
75:
76:        if let Some(idx) = trimmed.find("://") {
77:            // Root export (server://path)
78:            let host_port = &trimmed[..idx];
79:            let remainder = &trimmed[idx + 3..];
80:            let (host, port) = parse_host_port(host_port)?;
81:            let rel = normalize_relative_path_buf(remainder);
82:            return Ok(Self {
83:                host,
84:                port,
85:                path: RemotePath::Root { rel_path: rel },
86:            });
87:        }
88:
89:        if let Some(idx) = trimmed.find(":/") {
90:            // Module export (server:/module/...)
91:            let host_port = &trimmed[..idx];
92:            let remainder = &trimmed[idx + 2..];
93:            let (host, port) = parse_host_port(host_port)?;
94:
95:            let slash_idx = remainder.find('/').ok_or_else(|| {
96:                eyre!(
97:                    "module path must end with '/' (e.g., server:/module/ or server:/module/path)"
98:                )
99:            })?;
100:
101:            let module = &remainder[..slash_idx];
102:            if module.is_empty() {
103:                bail!("module name cannot be empty; expected server:/module/...");
104:            }
105:            let rest = &remainder[slash_idx + 1..];
106:            let rel = normalize_relative_path_buf(rest);
107:
108:            return Ok(Self {
109:                host,
110:                port,
111:                path: RemotePath::Module {
112:                    module: module.to_string(),
113:                    rel_path: rel,
114:                },
115:            });
116:        }
117:
118:        // Discovery (server or server:port)
119:        let (host, port) = parse_host_port(trimmed.trim_end())?;
120:        Ok(Self {
121:            host,
122:            port,
123:            path: RemotePath::Discovery,
124:        })
125:    }
