127:    /// Where, in an operand [`parse`](Self::parse) reads as holding a
128:    /// path, the path below the module — or below the default root —
129:    /// begins: its byte offset in `raw`. What stands before it is the
130:    /// daemon's part of the operand, separators and all (cr-uv1-4).
131:    pub fn path_offset(raw: &str) -> Option<usize> {
132:        let lead = raw.len() - raw.trim_start().len();
133:        let trimmed = &raw[lead..];
134:        if let Some(at) = trimmed.find("://") {
135:            return Some(lead + at + 3);
136:        }
137:        let at = trimmed.find(":/")?;
138:        let module_ends = trimmed[at + 2..].find('/')?;
139:        Some(lead + at + 2 + module_ends + 1)
140:    }
