142:    pub fn control_plane_uri(&self) -> String {
143:        // R58-F10: IPv6 literals must be bracketed in the URI's
144:        // authority component. The host field is stored bracket-
145:        // less (the parser strips them), so we re-bracket here.
146:        // A colon-containing host can only be IPv6 in our schema —
147:        // hostnames and IPv4 addresses never contain colons. Bare
148:        // `2001:db8::1:9031` is parsed by HTTP libraries as host
149:        // `2001` with garbage trailing, which is the bug.
150:        if self.host.contains(':') {
151:            format!("http://[{}]:{}", self.host, self.port)
152:        } else {
153:            format!("http://{}:{}", self.host, self.port)
154:        }
155:    }
