157:    /// Render just the `host[:port]` portion of this endpoint
158:    /// — drops the module / path suffix. Used by user-facing
159:    /// hints that reference the host as an argument
160:    /// (e.g. `blit jobs cancel <host> <id>`), where stitching
161:    /// the full canonical path back together would be wrong.
162:    /// Handles bracketed IPv6 via [`display_host`]; preserves
163:    /// non-default ports.
164:    pub fn host_port_display(&self) -> String {
165:        let host = display_host(&self.host);
166:        if self.port == Self::DEFAULT_PORT {
167:            host
168:        } else {
169:            format!("{}:{}", host, self.port)
170:        }
171:    }
