173:    /// Display helper used by CLI for canonical formatting.
174:    pub fn display(&self) -> String {
175:        let host = display_host(&self.host);
176:        let host_port = if self.port == Self::DEFAULT_PORT {
177:            host
178:        } else {
179:            format!("{}:{}", host, self.port)
180:        };
181:
182:        match &self.path {
183:            RemotePath::Module { module, rel_path } => {
184:                let mut path = format!("{}:/{}", host_port, module);
185:                if rel_path.as_os_str().is_empty() {
186:                    path.push('/');
187:                } else {
188:                    path.push('/');
189:                    path.push_str(&rel_path_to_string(rel_path));
190:                }
191:                path
192:            }
193:            RemotePath::Root { rel_path } => {
194:                if rel_path.as_os_str().is_empty() {
195:                    format!("{host_port}://")
196:                } else {
197:                    format!("{}://{}", host_port, rel_path_to_string(rel_path))
198:                }
199:            }
200:            RemotePath::Discovery => host_port,
201:        }
202:    }
203:}
