205:fn parse_host_port(authority: &str) -> Result<(String, u16)> {
206:    if authority.is_empty() {
207:        bail!("remote location missing host");
208:    }
209:
210:    if let Some(stripped) = authority.strip_prefix('[') {
211:        // IPv6 literal
212:        let closing = stripped
213:            .find(']')
214:            .ok_or_else(|| eyre!("unterminated IPv6 address: {}", authority))?;
215:        let host = &stripped[..closing];
216:        let remainder = &stripped[closing + 1..];
217:        let port = if let Some(port_str) = remainder.strip_prefix(':') {
218:            parse_port(port_str)?
219:        } else if remainder.is_empty() {
220:            RemoteEndpoint::DEFAULT_PORT
221:        } else {
222:            bail!("invalid host specification: {}", authority);
223:        };
224:        return Ok((host.to_string(), port));
