48:/// Parse a CLI / TUI source-or-destination input into an `Endpoint`.
49:/// Recognizes `host:/module/path` and `host://path` shapes as remote;
50:/// anything else is taken as a local filesystem path. Forward-slash
51:/// errors propagate so callers can show the user a clean diagnostic
52:/// instead of silently treating a misformatted remote as a local
53:/// path.
54:pub fn parse_transfer_endpoint(input: &str) -> Result<Endpoint> {
55:    match RemoteEndpoint::parse(input) {
56:        Ok(endpoint) => Ok(Endpoint::Remote(endpoint)),
57:        Err(err) => {
58:            // `RemoteEndpoint::parse` refuses with `NotRemote::LocalPath`
59:            // when `check_local_path` recognizes a local path — including
60:            // Windows drive paths (`C:/path`, `C:\path`) whose `:/` would
61:            // otherwise trip the remote-shaped-typo guard below. Honor
62:            // that lower-level classification: it's local, not a typo'd
63:            // remote. Read by its type, never its words (D-2026-11-24-1):
64:            // another refusal's message may quote the input.
65:            let not_remote = err.downcast_ref::<crate::remote::endpoint::NotRemote>();
66:            if not_remote == Some(&crate::remote::endpoint::NotRemote::LocalPath) {
67:                // D-2026-08-20-3: still name the daemon-address trap —
68:                // `1.2.3.4:9911//x/` lands here (the `:` is followed by
69:                // a digit, so `check_local_path` calls it local), and
70:                // silently creating a `./1.2.3.4:9911/` directory is
71:                // exactly the footgun. Warn, don't refuse.
72:                if let Some(msg) = remote_shaped_local_warning(input) {
73:                    log::warn!("{msg}");
74:                }
75:                return Ok(Endpoint::Local(PathBuf::from(input)));
76:            }
77:            if matches!(
78:                not_remote,
79:                Some(crate::remote::endpoint::NotRemote::Backslashes(_))
80:            ) {
81:                return Err(err);
82:            }
83:            // Anything that looks like a remote URI (scheme or
84:            // `host:/path`) must parse as remote; treating a typo'd
85:            // remote as a local path silently was a long-standing
86:            // footgun.
87:            if input.contains("://") || input.contains(":/") {
88:                Err(err)
89:            } else {
90:                if let Some(msg) = remote_shaped_local_warning(input) {
91:                    log::warn!("{msg}");
92:                }
93:                Ok(Endpoint::Local(PathBuf::from(input)))
94:            }
95:        }
96:    }
97:}
