427:impl PassResult {
428:    /// Fold a second session of the same pass into this result.
429:    fn merge(&mut self, other: PassResult) {
430:        self.files_transferred = self
431:            .files_transferred
432:            .saturating_add(other.files_transferred);
433:        self.bytes_transferred = self
434:            .bytes_transferred
435:            .saturating_add(other.bytes_transferred);
436:        self.failures.merge(other.failures);
437:        self.in_stream_carrier_used |= other.in_stream_carrier_used;
438:        self.files_resumed = self.files_resumed.saturating_add(other.files_resumed);
439:    }
