516:/// The pass loop, shared by every route. `run` executes one retry pass
517:/// with the prepared arguments (the retry-only set and the pass label
518:/// already threaded in) and returns that pass's result.
519:///
520:/// 2026-10-07 defect (b): Ctrl-C during the retry wait or a retry pass
521:/// stops the retries instead of killing the process, so the route still
522:/// prints the report of the pass that already ran — its deletions
523:/// included — and exits [`INTERRUPTED_EXIT`]. Once the handler has been
524:/// installed, a later Ctrl-C exits at once, as the default did.
525:pub(crate) async fn run_retry_passes<F, Fut>(
526:    args: &TransferArgs,
527:    main: PassFailures,
528:    run: F,
529:) -> Result<RetryOutcome>
530:where
531:    F: FnMut(TransferArgs) -> Fut,
532:    Fut: Future<Output = Result<PassResult>>,
533:{
534:    let armed = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
535:    let interrupt = {
536:        let armed = std::sync::Arc::clone(&armed);
537:        async move {
538:            armed.store(true, std::sync::atomic::Ordering::Relaxed);
539:            if tokio::signal::ctrl_c().await.is_err() {
540:                // No handler could be installed: never interrupt.
541:                std::future::pending::<()>().await;
542:            }
543:        }
544:    };
545:    let outcome = run_retry_passes_until(args, main, run, interrupt).await;
546:    if armed.load(std::sync::atomic::Ordering::Relaxed) {
547:        tokio::spawn(async {
548:            if tokio::signal::ctrl_c().await.is_ok() {
549:                std::process::exit(i32::from(INTERRUPTED_EXIT));
550:            }
551:        });
552:    }
553:    outcome
554:}
