556:/// [`run_retry_passes`] with the interrupt as an input, so tests can
557:/// trigger it.
558:pub(crate) async fn run_retry_passes_until<F, Fut, I>(
559:    args: &TransferArgs,
560:    main: PassFailures,
561:    mut run: F,
562:    interrupt: I,
563:) -> Result<RetryOutcome>
564:where
565:    F: FnMut(TransferArgs) -> Fut,
566:    Fut: Future<Output = Result<PassResult>>,
567:    I: Future<Output = ()>,
568:{
569:    let mut interrupt = std::pin::pin!(interrupt);
570:    let mut interrupted = false;
571:    let mut current = main;
572:    let mut added_files = 0u64;
573:    let mut added_bytes = 0u64;
574:    let mut passes_run = 0u32;
575:    let mut in_stream_carrier_used = false;
576:    let mut files_resumed = 0u64;
577:    // A dry run writes nothing, so nothing it reported can converge by
578:    // retrying; the report stands as the first pass produced it.
579:    let retries = if args.dry_run { 0 } else { args.retries };
580:    for pass in 1..=retries {
581:        if current.files_failed == 0 {
582:            break;
583:        }
584:        let (set, truncated) = current.retry_set();
585:        // cr-win-1: a retry pass compares exactly as the main pass did —
586:        // a failed write never leaves a target that looks finished (the
587:        // sink removes it or holds it one byte off the source's size), so
588:        // the user's compare is trusted here as on any later run. The one
589:        // exception is --ignore-existing: a path whose failure left this
590:        // run's own incomplete copy at the destination exists there now,
591:        // and that copy is not one the user asked to keep — those paths
592:        // retry apart, as such (cr-ecm13-1: the end that writes copies to
593:        // one only if nothing stands there by then, and keeps and
594:        // reports a file that does). cr-rework-1: they come from the exact set the
595:        // destination sends beside the failed paths, never the capped
596:        // report; if even that set did not fit, the paths it does not
597:        // name cannot be classified — retried with the flag a leftover is
