133:/// Git identity reported in the session handshake (informational
134:/// since D-2026-08-18-2; the gate is `CONTRACT_VERSION`).
135:///
136:/// Clean build inputs use the commit SHA. Dirty build inputs add a stable hash
137:/// of their scoped status, tracked diff, and untracked file contents. Every
138:/// watched workspace input is declared on every run, so separate Cargo target
139:/// profiles cannot retain different subsets of an older dirty tree.
140:fn git_build_suffix_inner(manifest_dir: &Path, emit_rerun: bool) -> String {
141:    let root = workspace_root(manifest_dir, emit_rerun);
142:    let Some(sha) = run_git_string(manifest_dir, &["rev-parse", "--short=12", "HEAD"])
143:        .filter(|sha| !sha.is_empty())
144:    else {
145:        return unknown_build_suffix();
146:    };
147:
148:    let Some(porcelain) = run_scoped_git(
149:        manifest_dir,
150:        &["status", "--porcelain=v1", "-z", "--untracked-files=all"],
151:    ) else {
152:        return unknown_build_suffix();
153:    };
154:    if porcelain.is_empty() {
155:        return sha;
156:    }
157:
158:    let Some(diff) = run_scoped_git(manifest_dir, &["diff", "--binary", "--no-ext-diff", "HEAD"])
159:    else {
160:        return unknown_build_suffix();
161:    };
162:    let mut hasher = std::collections::hash_map::DefaultHasher::new();
163:    porcelain.hash(&mut hasher);
164:    diff.hash(&mut hasher);
165:    hash_untracked_contents(&root, &porcelain, &mut hasher);
166:    format!("{sha}.dirty.{:016x}", hasher.finish())
167:}
