#[cfg(all(unix, test))]
mod r35_acquisition {
    use super::*;
    #[test]
    fn r35_refused_dangling_link_target() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("copy");
        let target = dir.path().join("new-target");
        std::os::unix::fs::symlink("new-target", &path).unwrap();
        CREATE_LOOK_FAULTS.lock().unwrap().push(path.clone());
        let failure = create_regular(&path).unwrap_err();
        CREATE_LOOK_FAULTS.lock().unwrap().retain(|p| p != &path);
        assert!(path.is_symlink());
        let marked = crate::remote::transfer::sink::leaves_in_place(&failure.into());
        assert!(!target.exists() || marked, "the empty target exists with no leftover flag");
